def test_mutation_kill_chain_make_context_name():
    """测试chain MultiCommand中make_context的name参数被改为None时行为不同"""
    runner = CliRunner()

    # 构造一个chain的MultiCommand，其中子命令会检查自己的name
    class NameCheckingCommand(Command):
        def make_context(self, info_name, args, parent=None, **extra):
            # 检查info_name是否为None
            if info_name is None:
                raise RuntimeError("info_name is None")
            return super().make_context(info_name, args, parent=parent, **extra)

    sub_cmd1 = NameCheckingCommand("sub1", callback=lambda: None)
    sub_cmd2 = NameCheckingCommand("sub2", callback=lambda: None)

    class ChainGroup(Group):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.chain = True

    chain_group = ChainGroup("chain_group")
    chain_group.add_command(sub_cmd1)
    chain_group.add_command(sub_cmd2)

    # 构造一个包含chain group的父命令
    @click.group()
    def cli():
        pass

    cli.add_command(chain_group)

    # 触发completion，会调用_resolve_context
    # 当chain group处理参数时，会进入while args循环
    # 在变异点，make_context的name参数从name变为None
    # 如果name为None，NameCheckingCommand会抛出RuntimeError
    result = runner.invoke(cli, ["chain_group", "sub1", "sub2"], prog_name="test_cli")

    # 原代码中，name会被正确传递，不会抛出异常，exit_code为0
    # 变异后，name为None，NameCheckingCommand抛出RuntimeError，exit_code不为0
    assert result.exit_code == 0
    assert "info_name is None" not in result.output

import pytest
from jinja2 import Environment
from jinja2.lexer import TokenStream

class BadExtension:
    identifier = "bad_extension"
    priority = 0

    def __init__(self, environment):
        self.environment = environment

    def preprocess(self, source, name, filename=None):
        return source

    def filter_stream(self, stream):
        # Return a plain list instead of TokenStream
        return list(stream)

def test_mutation_kill_tokenstream_arg():
    env = Environment(extensions=[BadExtension])
    with pytest.raises(TypeError):
        env.parse("{{ 1 + 1 }}")

